const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');
const mk = () => new ProfileService({ displayName: 'before', tags: ['old'] });
const bad = (input) => {
  const s = mk();
  assert.throws(() => s.patch(input), /^Error: invalid profile$/, JSON.stringify(input));
  assert.deepEqual(s.profile, { displayName: 'before', tags: ['old'] });
};

// Valid cases
let s = mk();
assert.deepEqual(s.patch({}), { displayName: 'before', tags: ['old'] });
assert.deepEqual(s.patch(Object.create(null)), { displayName: 'before', tags: ['old'] });
assert.deepEqual(s.patch({ displayName: '  Ann  ' }), { displayName: 'Ann', tags: ['old'] });
assert.deepEqual(s.patch({ displayName: null }), { displayName: null, tags: ['old'] });
assert.deepEqual(s.patch({ displayName: 'x'.repeat(40) }).displayName, 'x'.repeat(40));
assert.deepEqual(s.patch({ tags: [] }), { displayName: 'x'.repeat(40), tags: [] });
assert.deepEqual(s.patch({ tags: [' a ', 'b', 'c', 'd', 'e'.repeat(12)] }).tags, ['a', 'b', 'c', 'd', 'e'.repeat(12)]);
assert.deepEqual(s.patch({ tags: null }).tags, []);

// Input not mutated, caller array not reused, returned value detached from storage
s = mk();
const tags = [' x '];
const input = { displayName: ' n ', tags };
const out = s.patch(input);
assert.deepEqual(input, { displayName: ' n ', tags: [' x '] });
assert.notEqual(s.profile.tags, tags);
tags.push('y');
out.tags.push('z');
assert.deepEqual(s.profile.tags, ['x']);

// Invalid cases leave storage unchanged
for (const v of [null, undefined, 1, 'x', true, [], [1], new Date(), new (class P {})()]) bad(v);
bad({ extra: 1 });
bad({ displayName: 'ok', extra: undefined });
bad({ [Symbol('s')]: 1 });
bad({ displayName: '' });
bad({ displayName: '   ' });
bad({ displayName: 'x'.repeat(41) });
bad({ displayName: 5 });
bad({ displayName: undefined });
bad({ tags: undefined });
bad({ tags: 'a' });
bad({ tags: [1] });
bad({ tags: [''] });
bad({ tags: ['  '] });
bad({ tags: ['a', ' a'] });
bad({ tags: ['a', 'b', 'c', 'd', 'e', 'f'] });
bad({ tags: ['x'.repeat(13)] });
bad({ tags: [, 'a'] }); // sparse
bad({ displayName: 'valid', tags: [1] }); // atomic: valid name not applied
bad(Object.defineProperty({}, 'displayName', { get: () => 'x', enumerable: true }));
console.log('patch checks passed');

